}

/**
 * Clear stale end-loop markers (older than 1 hour).
 * AC: @ralph-end-loop ac-cleanup
 */
async function clearStaleEndLoopMarker(rootDir: string): Promise<boolean> {
  const marker = await readEndLoopMarker(rootDir);
