export const DEFAULT_SUBAGENT_PREFIX = "[REVIEW SUBAGENT]";

// ============================================================================
// Skill Invocation Names
// ============================================================================
// Ralph prompts reference skills by invocation name. These are defined as
// constants so they're easy to update as core skills are created under the
// kspec: namespace. Projects can also override these via meta configuration
// in the future.

/** Skill invocation for task-work in ralph worker prompt */
export const SKILL_TASK_WORK = "/task-work";

/** Skill invocation for reflect in ralph reflect prompt */
export const SKILL_REFLECT = "/reflect";

/** Skill invocation for PR review in ralph subagent prompt */
export const SKILL_PR_REVIEW = "/pr-review";

/**
 * Default ACP prompt timeout for ralph agents: 30 minutes.
 * The framing layer default (5 min) is too aggressive — API slowness,
 * extended thinking, and large context processing can exceed it even
 * with the keepalive mechanism (which resets on tool calls/notifications).
 */
export const RALPH_PROMPT_TIMEOUT = 30 * 60 * 1000;

// ============================================================================
// Prompt Builder
// ============================================================================

/**
 * Build the prompt for a PR review subagent.
 * AC: @ralph-subagent-spawning ac-2, ac-10, ac-12
 */
export function buildSubagentPrompt(context: SubagentContext): string {
  const specSection = context.specWithACs
    ? `
## Linked Spec with Acceptance Criteria

\`\`\`json
${JSON.stringify(context.specWithACs, null, 2)}
\`\`\`

**Verify all ACs have test coverage before merging.**
`
    : "";

  return `# PR Review Subagent

You are a subagent spawned by ralph to REVIEW a PR and merge it only if clean.

## Role Boundary

You are a REVIEWER, not a fixer. Your responsibilities:
- Review code quality, AC coverage (own + trait), spec alignment
- Post findings as inline PR comments with severity (MUST-FIX:, SHOULD-FIX:, SUGGESTION:)
- Merge the PR ONLY if all quality gates pass (no MUST-FIX or SHOULD-FIX items)
- Complete the task after merge

You MUST NOT:
- Fix code issues yourself
- Push commits to the PR branch
- Add or modify tests
- Make any code changes

If you find issues:
1. Post them as inline PR comments with severity prefix
2. Transition the task to needs_work: \`kspec task needs-work ${context.taskRef} --reason "findings..."\`
3. Exit — the worker agent will fix issues in the next iteration

## Context

- **Task:** \`${context.taskRef}\`
- **Branch:** \`${context.gitBranch}\`

### Task Details

\`\`\`json
${JSON.stringify(context.taskDetails, null, 2)}
\`\`\`
${specSection}
## Instructions

Run the PR review skill:

\`\`\`
${SKILL_PR_REVIEW} ${context.taskRef}
\`\`\`

## Current State
\`\`\`json
${JSON.stringify(sessionCtx, null, 2)}
\`\`\`

## Instructions

Run the task-work skill in loop mode:

\`\`\`
${SKILL_TASK_WORK} loop
\`\`\`

${modeDescription}

**Normal flow:** Work on a task, create a PR, then stop responding. Ralph continues automatically —
it checks for remaining eligible tasks at the start of each iteration and exits the loop itself when none remain.

**Do NOT call \`end-loop\` after completing a task.** Simply stop responding.
\`end-loop\` is a rare escape hatch for when work is stalling across multiple iterations with no progress — not a normal exit path.
`;
}

/**
 * Build the reflect prompt sent after task-work completes.
 * Ralph sends this as a separate prompt to ensure reflection always happens.
 */
function buildReflectPrompt(
  iteration: number,
  maxLoops: number,
  sessionId: string,
): string {
  const isFinal = iteration === maxLoops;

  return `# Kspec Automation Session - Reflection

**Session ID:** \`${sessionId}\`
**Iteration:** ${iteration} of ${maxLoops}
**Phase:** Post-task reflection

## Instructions

Run the reflect skill in loop mode:

\`\`\`
${SKILL_REFLECT} loop
\`\`\`

Loop mode means: high-confidence captures only, must search existing before capturing, no user prompts.
${
  isFinal
    ? `
**FINAL ITERATION** - This is the last chance to capture insights from this session.
`
    : ""
}
Exit when reflection is complete.
`;
}

